import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        double[] p = new double[n];
        double[] res = new double[1 << n];
        double[] q = new double[n];

        for (int i = 0; i < n; i++) {
            p[i] = sc.nextDouble();
            res[1 << i] = p[i];
            q[i] = 0.0;
        }

        for (int mask = 1; mask < (1 << n); mask++) {
            // Collect selected and remaining indices
            int[] selectedIndices = new int[n];
            int selectedCount = 0;
            int[] remainingIndices = new int[n];
            int remainingCount = 0;
            double sumRemaining = 0.0;

            for (int j = 0; j < n; j++) {
                if (((mask >> j) & 1) == 1) {
                    selectedIndices[selectedCount++] = j;
                } else {
                    remainingIndices[remainingCount++] = j;
                    sumRemaining += p[j];
                }
            }

            if (selectedCount == m || (selectedCount < m && sumRemaining < 1e-15)) {
                for (int i = 0; i < selectedCount; i++) {
                    int x = selectedIndices[i];
                    q[x] += res[mask];
                }
            } else if (selectedCount < m) {
                for (int i = 0; i < remainingCount; i++) {
                    int x = remainingIndices[i];
                    int newMask = mask | (1 << x);
                    res[newMask] += res[mask] * p[x] / sumRemaining;
                }
            }
        }

        for (int i = 0; i < n; i++) {
            System.out.printf("%.15f ", q[i]);
        }
        System.out.println();
        sc.close();
    }
}
